/** Client merge page. Hand-maintained JavaScript; not generated by XSLT. */
"use strict";

function ClientMerge_View(id, options) {
	options = options || {};
	this.selected = new Map();
	this.mainId = null;
	this.busy = false;
	this.selectionReady = false;
	this.requestVersion = 0;
	this.panel = null;
	this.list = null;
	this.mergeButton = null;
	this.clearButton = null;
	this.refreshButton = null;
	this.errorNode = null;
	this.statusNode = null;
	this.gridNode = null;
	var self = this;

	this.onGridDblClick = function(event) {
		if (self.busy || !self.selectionReady || !(event.target instanceof Element)) {
			return;
		}
		if (event.target.closest("a, button, input, select, textarea")) {
			return;
		}
		var row = event.target.closest("tr[modelIndex]");
		if (!row || !self.gridNode || !self.gridNode.contains(row)) {
			return;
		}
		var grid = self.getElement("grid");
		grid.setModelToCurrentRow(row);
		var clientId = Number(grid.getModel().getFieldValue("id"));
		if (!Number.isInteger(clientId) || clientId <= 0 || self.selected.has(clientId)) {
			return;
		}
		if (self.selected.size >= 100) {
			self.showRequestError(new Error("Можно выбрать не более 100 клиентов."));
			return;
		}
		self.runMutation("merge_select", {client_id: clientId});
	};
	this.onMerge = function() {
		self.merge();
	};
	this.onClear = function() {
		self.runMutation("merge_clear_selection", {});
	};
	this.onReload = function() {
		self.reload();
	};

	options.addElement = function() {
		var model = options.models && options.models.ClientMergeList_Model;
		model = model || new ClientMergeList_Model();
		var controller = new Client_Controller();
		var constants = {doc_per_page_count: null};
		window.getApp().getConstantManager().get(constants);
		var paginationClass = window.getApp().getPaginationClass();
		var columns = [
			{id: "name", caption: "Наименование", sort: "asc"},
			{id: "inn", caption: "ИНН"},
			{id: "phone_cel", caption: "Телефон"},
			{id: "orders_count", caption: "Количество заказов"}
		];
		var cells = columns.map(function(column) {
			return new GridCellHead(id + ":grid:head:" + column.id, {
				value: column.caption,
				sortable: true,
				sort: column.sort,
				columns: [new GridColumn({field: model.getField(column.id)})]
			});
		});
		var grid = new GridAjx(id + ":grid", {
			model: model,
			controller: controller,
			readPublicMethod: controller.getPublicMethod("get_merge_list"),
			insertPublicMethod: null,
			updatePublicMethod: null,
			deletePublicMethod: null,
			editPublicMethod: null,
			editInline: false,
			cmdInsert: false,
			cmdEdit: false,
			cmdCopy: false,
			cmdDelete: false,
			cmdPrint: false,
			commands: new GridCmdContainerAjx(id + ":grid:cmd", {
				cmdInsert: false,
				cmdEdit: false,
				cmdCopy: false,
				cmdDelete: false,
				cmdPrint: false,
				cmdExport: false,
				cmdFilter: false
			}),
			head: new GridHead(id + ":grid:head", {
				elements: [new GridRow(id + ":grid:head:row0", {elements: cells})]
			}),
			pagination: new paginationClass(id + "_page", {
				countPerPage: constants.doc_per_page_count.getValue()
			}),
			autoRefresh: false,
			refreshInterval: 0,
			rowSelect: true,
			focus: true
		});
		// Only our dblclick handler adds a client; Grid still handles row highlighting.
		grid.setOnSelect(null);
		this.addElement(grid);
	};
	ClientMerge_View.superclass.constructor.call(this, id, options);
}
extend(ClientMerge_View, ViewAjxList);

ClientMerge_View.prototype.request = function(methodId, values) {
	return new Promise(function(resolve, reject) {
		try {
			var method = new Client_Controller().getPublicMethod(methodId);
			Object.keys(values || {}).forEach(function(fieldId) {
				method.setFieldValue(fieldId, values[fieldId]);
			});
			method.run({
				requestType: methodId.indexOf("get_") === 0 ? "get" : "post",
				ok: resolve,
				fail: function(response, errorCode, errorText) {
					var message = window.getApp().formatError(errorCode, errorText);
					reject(new Error(message || errorText || "Не удалось выполнить запрос."));
				}
			});
		}
		catch (error) {
			reject(error);
		}
	});
};

ClientMerge_View.prototype.reloadState = async function(version) {
	this.selectionReady = false;
	var response = await this.request("get_merge_selected", {});
	if (version !== this.requestVersion || !this.panel) {
		return;
	}
	var model = response.getModel("ClientMergeSelectedList_Model");
	if (!model) {
		throw new Error("Сервер не вернул список выбранных клиентов.");
	}
	var selected = new Map();
	while (model.getNextRow()) {
		var clientId = Number(model.getFieldValue("id"));
		selected.set(clientId, {
			id: clientId,
			name: String(model.getFieldValue("name") || ""),
			inn: String(model.getFieldValue("inn") || ""),
			phone: String(model.getFieldValue("phone_cel") || ""),
			ordersCount: String(model.getFieldValue("orders_count") || "0")
		});
	}
	this.selected = selected;
	if (!this.selected.has(this.mainId)) {
		var first = this.selected.keys().next();
		this.mainId = first.done ? null : first.value;
	}
	this.renderSelection();
	var grid = this.getElement("grid");
	await new Promise(function(resolve, reject) {
		grid.onRefresh(resolve, function() {
			reject(new Error("Не удалось обновить список клиентов. Нажмите «Обновить списки»."));
		});
	});
	if (version === this.requestVersion && this.panel) {
		this.selectionReady = true;
	}
};

ClientMerge_View.prototype.reload = async function() {
	if (this.busy || !this.panel) {
		return;
	}
	var version = this.requestVersion;
	this.busy = true;
	this.showRequestError(null);
	this.renderSelection();
	try {
		await this.reloadState(version);
	}
	catch (error) {
		if (version === this.requestVersion) {
			this.showRequestError(error);
		}
	}
	finally {
		if (version === this.requestVersion) {
			this.busy = false;
			this.renderSelection();
		}
	}
};

ClientMerge_View.prototype.runMutation = async function(methodId, values, successMessage) {
	if (this.busy || !this.selectionReady || !this.panel) {
		return;
	}
	var version = this.requestVersion;
	this.busy = true;
	this.showRequestError(null);
	this.renderSelection();
	var completed = false;
	try {
		await this.request(methodId, values);
		if (version !== this.requestVersion || !this.panel) {
			return;
		}
		completed = true;
		// Selection changes the available row count; avoid leaving an empty last page.
		var pagination = this.getElement("grid").getPagination();
		if (pagination) {
			pagination.setFrom(0);
		}
		await this.reloadState(version);
		if (successMessage && version === this.requestVersion && this.panel) {
			window.alert(successMessage);
		}
	}
	catch (error) {
		if (version === this.requestVersion && this.panel) {
			this.showRequestError(completed ? new Error("Операция выполнена, но списки не обновлены. Нажмите «Обновить списки». " + error.message) : error);
			// A failed network response can hide a committed change; recover server state.
			if (!completed) {
				try {
					await this.reloadState(version);
				}
				catch (reloadError) {
					this.selectionReady = false;
				}
			}
		}
	}
	finally {
		if (version === this.requestVersion) {
			this.busy = false;
			this.renderSelection();
		}
	}
};

ClientMerge_View.prototype.showRequestError = function(error) {
	if (this.errorNode) {
		this.errorNode.textContent = error ? error.message : "";
		this.errorNode.hidden = !error;
	}
};

ClientMerge_View.prototype.merge = function() {
	if (this.busy || !this.selectionReady || this.selected.size < 2 || this.mainId === null) {
		return;
	}
	var main = this.selected.get(this.mainId);
	if (!main || !window.confirm("Объединить " + this.selected.size + " клиентов в «" + main.name + "» (код " + main.id + ", заказов: " + main.ordersCount + ")? Остальные выбранные клиенты будут удалены.")) {
		return;
	}
	this.runMutation("merge_selected", {
		main_client_id: main.id,
		client_ids: Array.from(this.selected.keys()).join(",")
	}, "Клиенты объединены.");
};

ClientMerge_View.prototype.renderSelection = function() {
	if (!this.list || !this.mergeButton) {
		return;
	}
	var self = this;
	var disabled = this.busy || !this.selectionReady;
	this.list.replaceChildren();
	if (!this.selected.size) {
		this.list.textContent = this.busy ? "Загрузка выбранных клиентов…" : "Клиенты пока не выбраны.";
	}
	else {
		var table = document.createElement("table");
		table.className = "table table-bordered table-striped";
		var head = document.createElement("thead");
		var headRow = document.createElement("tr");
		["Главный", "Наименование", "Код", "ИНН", "Телефон", "Количество заказов", ""].forEach(function(caption) {
			var cell = document.createElement("th");
			cell.scope = "col";
			cell.textContent = caption;
			headRow.appendChild(cell);
		});
		head.appendChild(headRow);
		table.appendChild(head);
		var body = document.createElement("tbody");
		this.selected.forEach(function(client) {
			var row = document.createElement("tr");
			var radioCell = document.createElement("td");
			var radio = document.createElement("input");
			radio.type = "radio";
			radio.name = self.getNode().id + ":mainClient";
			radio.value = String(client.id);
			radio.checked = client.id === self.mainId;
			radio.disabled = disabled;
			radio.setAttribute("aria-label", "Главный клиент: " + client.name);
			radio.addEventListener("change", function() {
				self.mainId = client.id;
			});
			radioCell.appendChild(radio);
			row.appendChild(radioCell);
			[client.name, String(client.id), client.inn, client.phone, client.ordersCount].forEach(function(value) {
				var cell = document.createElement("td");
				cell.textContent = value;
				row.appendChild(cell);
			});
			var removeCell = document.createElement("td");
			var remove = document.createElement("button");
			remove.type = "button";
			remove.className = "btn btn-link btn-xs";
			var removeIcon = document.createElement("span");
			removeIcon.className = "glyphicon glyphicon-remove";
			removeIcon.setAttribute("aria-hidden", "true");
			remove.appendChild(removeIcon);
			remove.disabled = disabled;
			remove.setAttribute("aria-label", "Убрать " + client.name);
			remove.addEventListener("click", function() {
				self.runMutation("merge_unselect", {client_id: client.id});
			});
			removeCell.appendChild(remove);
			row.appendChild(removeCell);
			body.appendChild(row);
		});
		table.appendChild(body);
		var wrapper = document.createElement("div");
		wrapper.className = "table-responsive";
		wrapper.appendChild(table);
		this.list.appendChild(wrapper);
	}
	this.panel.setAttribute("aria-busy", this.busy ? "true" : "false");
	this.statusNode.textContent = this.busy ? "Обновление…" : "Выбрано клиентов: " + this.selected.size;
	this.mergeButton.disabled = disabled || this.selected.size < 2 || this.mainId === null;
	this.clearButton.disabled = disabled || !this.selected.size;
	this.refreshButton.disabled = this.busy;
};

ClientMerge_View.prototype.toDOM = function(parent) {
	ClientMerge_View.superclass.toDOM.call(this, parent);
	this.requestVersion++;
	this.busy = false;
	this.selectionReady = false;
	var root = this.getNode();
	this.panel = document.createElement("div");
	this.panel.className = "panel panel-default";
	var body = document.createElement("div");
	body.className = "panel-body";
	var help = document.createElement("p");
	help.textContent = "Добавьте клиентов двойным щелчком по строке в списке ниже. Выбранные клиенты скрываются из нижнего списка и сохраняются для вашего пользователя. Выберите главного клиента с учетом количества заказов. Остальные клиенты будут удалены; их связи перейдут главному. Реквизиты главного клиента сохраняются.";
	body.appendChild(help);
	this.errorNode = document.createElement("div");
	this.errorNode.className = "alert alert-danger";
	this.errorNode.setAttribute("role", "alert");
	this.errorNode.hidden = true;
	body.appendChild(this.errorNode);
	this.list = document.createElement("div");
	this.list.setAttribute("aria-live", "polite");
	body.appendChild(this.list);
	var controls = document.createElement("div");
	controls.className = "btn-toolbar";
	this.mergeButton = document.createElement("button");
	this.mergeButton.type = "button";
	this.mergeButton.className = "btn btn-danger";
	this.mergeButton.textContent = "Объединить выбранных клиентов";
	this.mergeButton.addEventListener("click", this.onMerge);
	controls.appendChild(this.mergeButton);
	this.clearButton = document.createElement("button");
	this.clearButton.type = "button";
	this.clearButton.className = "btn btn-default";
	this.clearButton.textContent = "Очистить выбор";
	this.clearButton.addEventListener("click", this.onClear);
	controls.appendChild(this.clearButton);
	this.refreshButton = document.createElement("button");
	this.refreshButton.type = "button";
	this.refreshButton.className = "btn btn-default";
	this.refreshButton.textContent = "Обновить списки";
	this.refreshButton.addEventListener("click", this.onReload);
	controls.appendChild(this.refreshButton);
	body.appendChild(controls);
	this.statusNode = document.createElement("p");
	this.statusNode.className = "help-block";
	this.statusNode.setAttribute("role", "status");
	body.appendChild(this.statusNode);
	this.panel.appendChild(body);
	this.gridNode = this.getElement("grid").getNode();
	var gridContainer = this.gridNode;
	while (gridContainer.parentElement && gridContainer.parentElement !== root) {
		gridContainer = gridContainer.parentElement;
	}
	root.insertBefore(this.panel, gridContainer.parentElement === root ? gridContainer : null);
	this.gridNode.addEventListener("dblclick", this.onGridDblClick);
	this.renderSelection();
	this.reload();
};

ClientMerge_View.prototype.delDOM = function() {
	this.requestVersion++;
	if (this.gridNode) {
		this.gridNode.removeEventListener("dblclick", this.onGridDblClick);
	}
	if (this.panel) {
		this.panel.remove();
	}
	this.panel = null;
	this.list = null;
	this.mergeButton = null;
	this.clearButton = null;
	this.refreshButton = null;
	this.errorNode = null;
	this.statusNode = null;
	this.gridNode = null;
	this.busy = false;
	this.selectionReady = false;
	ClientMerge_View.superclass.delDOM.call(this);
};
